{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "FK788, which shares the phenoxyacetic acid and fused bicyclic scaffold with the query, showed 55% oral bioavailability in healthy volunteers after oral dosing, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Cicaprost, a prostacyclin analogue structurally related to the query, demonstrated complete absolute oral bioavailability in healthy male volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Iloprost, another prostacyclin analogue with a similar cyclopentane core and carboxylic acid side chain, showed absolute oral bioavailability of 56% and 63% in TAO patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "2,4-D, containing the same aryloxyacetic acid moiety as the query, was rapidly and completely orally bioavailable in humans, supporting high absorption of this acid functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pravastatin, a carboxylic acid drug with extensive hepatic first-pass metabolism, had absolute oral bioavailability of only 18% in healthy volunteers; this is a structurally more distant low-F example and is outweighed by the prostacyclin analogue evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Propafenone showed low median oral bioavailability (15.5%) due to presystemic metabolism, but lacks the prostacyclin-like scaffold and carboxylic acid of the query; this contradictory evidence is weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a prostacyclin-like molecule with an aryloxyacetic acid. The most relevant analogues—FK788 (55%), cicaprost (complete), iloprost (56-63%), and 2,4-D (complete)—consistently support high oral bioavailability. Low-F analogues (pravastatin, propafenone) are structurally more distant and do not override this pattern. Prediction: high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the query molecule.",
    "No human data on first-pass metabolism, transporter efflux, or solubility-limited absorption for the query.",
    "Morgan similarities to evidence molecules are moderate (0.23-0.30), limiting exact transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

